head.script:
scwin.onpageload = function() {
    console.log("onpageload " + $p.getParameter("w2xPath") + " Frame");
};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick = function(e) {
    requires("uiplugin.popup");
    var options = {
        id: "popup1",
        type: "iframePopup",
        width: "700px",
        height: "600px",
        top: "130px",
        left: "400px",
        popupName: "openPopup1",
        modal: true,
        scrollbars: "true",
        resizable: "true",
        menubar: true,
        frameMode: "iframe",
        alwaysOnTop: false,
        useControl: true
    };
    $p.openPopup("popup_onpageunload_WPFF-258_(WSQ-3580)_iframe.xml", options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ibx_openPopup').click()");
    WebSquare.wUnit.addCommand("pause", "2500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#textbox_status').text() == 'onpageload : '+$p.id+'popup1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
